"""Local review surface. Preserve the open player during silent refresh."""
from tubeforge.api.studio_shell import STUDIO_STATIC_MENU_SCRIPT, wrap_studio_page

_MAIN_HTML = r'''<main class="mx-auto grid max-w-content gap-6">
<header class="grid gap-1 border-b border-tf-line pb-5"><h1>Day review</h1><p class="max-w-form text-md text-tf-muted">Review the exact local video. Ready means staged for later publishing.</p></header>
<section class="grid min-w-0 gap-4 rounded-lg border border-tf-line bg-tf-surface p-5">
<div class="flex flex-wrap items-end gap-3"><div><label class="grid gap-1.5" for="day">Day (publish metadata; leave blank for all)</label><input id="day" type="date"></div><button id="refresh" type="button">Refresh</button></div>
<p id="notice" class="text-sm text-tf-muted" role="status" aria-live="polite">Loading review queue…</p>
</section>
<section class="grid min-w-0 gap-4 rounded-lg border border-tf-line bg-tf-surface p-5" aria-label="Channel safety"><h2>Channel safety</h2><p class="text-sm text-tf-muted">Warnings are review signals. Publish dates remain metadata.</p><p id="safetyStatus" class="text-sm text-tf-muted" role="status"></p><ul id="safetyWarnings" aria-live="polite"><li>Loading channel checks…</li></ul><a href="/docs/channel-safety-checklist">Before-upload checklist</a></section>
<div class="grid items-start gap-5 lg:grid-cols-[minmax(220px,1fr)_minmax(0,2fr)]">
<section class="grid min-w-0 gap-4 rounded-lg border border-tf-line bg-tf-surface p-5" aria-label="Day videos"><ul id="reviewList" class="grid list-none gap-2 pl-0"></ul></section>
<section class="grid min-w-0 gap-4 rounded-lg border border-tf-line bg-tf-surface p-5" id="detail" aria-label="Selected video"><p>Select a short to review its video, QA, and script.</p></section>
</div>
</main>'''

_PAGE_HEAD = r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Day review — TubeForge</title><style type="text/tailwindcss">
@layer base {
  button{@apply inline-flex h-9 items-center justify-center rounded-md border border-tf-line-strong bg-tf-raised px-4 text-base font-medium text-tf-text hover:border-tf-muted disabled:cursor-not-allowed disabled:text-tf-faint;}
  button[data-action=approve],button[data-action=ready],button[data-confirm]{@apply border-transparent bg-tf-accent font-semibold text-tf-accent-ink hover:brightness-110 disabled:bg-tf-raised disabled:text-tf-faint;}
  input:not([type=checkbox]),select{@apply h-9 rounded-md border border-tf-line-strong bg-tf-input px-3 text-base text-tf-text;}
  input[type=checkbox]{@apply h-4 w-4 accent-tf-accent;}
  label{@apply text-sm font-medium text-tf-text;}
  a{@apply text-tf-text underline decoration-tf-line-strong underline-offset-4 hover:decoration-tf-accent;}
  h1{@apply m-0 text-xl font-semibold text-tf-text;}
  h2{@apply m-0 text-lg font-semibold text-tf-text;}
  h3{@apply m-0 text-md font-semibold text-tf-text;}
  p{@apply m-0 text-base text-tf-text;}
  ul,ol{@apply m-0 grid gap-2 pl-5 text-base;}
  pre{@apply m-0 overflow-auto whitespace-pre-wrap break-words rounded-md border border-tf-line bg-tf-input p-3 font-mono text-xs text-tf-muted;}
  details summary{@apply cursor-pointer text-sm text-tf-muted hover:text-tf-text;}
  video{@apply block w-full max-h-[65vh] rounded-md bg-tf-input;}
  img{@apply w-full max-w-60 rounded-md;}
}
</style>
'''


def render_review_html(username: str | None = None) -> str:
    return (
        _PAGE_HEAD
        + wrap_studio_page('batch', username, 'Workspace / Batch plans / Day review', _MAIN_HTML)
        + r'''
<script>
const list=document.querySelector('#reviewList'),detail=document.querySelector('#detail'),notice=document.querySelector('#notice'),day=document.querySelector('#day');let selected=null,items=[],busy=false,signature='',safetySignature='';
const BADGE_BASE='inline-flex items-center rounded-sm px-2 py-0.5 text-xs font-semibold ';
const BADGE_BAD=BADGE_BASE+'bg-tf-bad-soft text-tf-bad',BADGE_WARN=BADGE_BASE+'bg-tf-warn-soft text-tf-warn',BADGE_OK=BADGE_BASE+'bg-tf-ok-soft text-tf-ok';
function rawFileError(text){return /errno|no such file|traceback|permission|\.(jpg|png|mp4)\b|data\/artifacts/i.test(text);}
function friendlyThumbReason(reason){const text=String(reason||'');return !text||rawFileError(text)?'Thumbnail unavailable: the file is missing or unreadable.':text;}
function friendlyVideoError(error){const text=String(error||'');return !text?'The final video is not available for review yet.':rawFileError(text)?'The final video file is missing or unreadable, so it cannot be reviewed.':text;}
function node(tag,text){const el=document.createElement(tag);if(text!==undefined)el.textContent=text;return el;}
function qaChecks(qa){if(!qa||!qa.output)return null;try{const parsed=JSON.parse(qa.output);return Array.isArray(parsed)?parsed:null;}catch(_){return null;}}
function qaList(qa){
  const checks=qaChecks(qa);
  if(!qa)return node('p','No QA result recorded. Approval is disabled until checks pass for this video.');
  if(!checks){const fallback=node('pre',qa.error||qa.output||'QA did not record a readable result.');return fallback;}
  const list=node('ul');list.className='grid list-none gap-1.5 pl-0';
  for(const {level,check,detail} of checks){
    const item=node('li');item.className='flex items-start gap-2 text-sm';
    const badge=node('span',level);badge.className=level==='FAIL'?BADGE_BAD:level==='WARN'?BADGE_WARN:BADGE_OK;
    item.append(badge,node('span',' '+check+': '+detail));
    list.append(item);
  }
  if(!checks.length)list.append(node('li','No checks recorded.'));
  return list;
}
function show(item){selected=item;pendingConfirm=null;detail.replaceChildren();const stateLabel=node('p',`Review: ${item.state}${item.decision?' · '+item.decision:''} · Production: ${item.production_state}`);stateLabel.id='reviewStatus';detail.append(node('h2',item.short.title),stateLabel);if(item.preview_url){const video=node('video');video.controls=true;video.preload='metadata';video.src=item.preview_url;if(item.thumbnail_url)video.poster=item.thumbnail_url;detail.append(video);}else detail.append(node('p',friendlyVideoError(item.error)));
if(item.thumbnail_url){const image=node('img');image.src=item.thumbnail_url;image.alt=`Thumbnail for ${item.short.title}`;detail.append(image);}else detail.append(node('p',friendlyThumbReason(item.thumbnail_result?.reason)+' Brief: '+(item.short.thumbnail?.text||'No text')+' · '+(item.short.thumbnail?.visual||'No visual brief')));
detail.append(node('h3','QA result'),qaList(item.qa));
const disclosure=item.disclosure||{};detail.append(node('h3','Disclosure and rights'),node('p',disclosure.description_text||'Disclosure evidence unavailable.'),node('p',(disclosure.missing||[]).join(', ')||(disclosure.originality?.problems||[]).join('; ')||'Source and audio evidence available.'));
const evidenceDetails=node('details');evidenceDetails.append(node('summary','Sources and audio rights'));const evidenceList=node('ul');for(const source of disclosure.sources||[])evidenceList.append(node('li',`${source.title||source.source_id}: ${source.url}`));for(const asset of disclosure.audio_licenses||[])evidenceList.append(node('li',`${asset.asset}: ${asset.license_name||asset.license||asset.note||'Terms missing'}${asset.attribution?' · '+asset.attribution:''}`));evidenceDetails.append(evidenceList);detail.append(evidenceDetails);
const disclosureLabel=node('label','Does this video require the platform AI disclosure? ');const disclosureChoice=node('select');disclosureChoice.id='disclosureChoice';for(const [value,label] of [['','Choose after reviewing'],['yes','Yes — realistic altered or synthetic content'],['no','No — reviewed as outside that requirement']]){const option=node('option',label);option.value=value;disclosureChoice.append(option);}disclosureChoice.value=disclosure.platform_disclosure_required===true?'yes':disclosure.platform_disclosure_required===false?'no':'';disclosureLabel.append(disclosureChoice);detail.append(disclosureLabel);

const actions=node('div');actions.id='actions';actions.className='flex flex-wrap gap-2';for(const [action,label] of [['approve','Approve'],['reject','Reject'],['regenerate','Regenerate'],['ready','Stage as ready']]){const button=node('button',label);button.type='button';button.dataset.action=action;button.setAttribute('aria-describedby','actionHint');button.disabled=!item.available||busy||(action==='approve'&&(!item.qa_ok||!item.disclosure?.eligible))||(action==='ready'&&(!item.qa_ok||item.state!=='approved'||!item.thumbnail_url));button.onclick=()=>action==='reject'||action==='regenerate'?askConfirm(action):decide(action);actions.append(button);}const exportLink=node('a','Open export');exportLink.id='exportLink';exportLink.href=item.export_url||'#';exportLink.hidden=!item.export_url;exportLink.target='_blank';exportLink.rel='noopener';detail.append(exportLink);const scriptSections=item.script&&Array.isArray(item.script.script_sections)?item.script.script_sections:null;const scriptSummary=scriptSections?{narration:scriptSections.map(s=>s.narration).filter(Boolean),hook:item.short.hook,beats:item.short.beats,cta:item.short.cta}:{narration:item.short.narration,hook:item.short.hook,beats:item.short.beats,cta:item.short.cta};const hints=[];if(!item.available)hints.push('Video files for this short are unavailable, so review actions are off.');else{if(!item.qa_ok)hints.push('Approve is off until QA passes for this video.');else if(!item.disclosure?.eligible)hints.push('Approve is off: '+((item.disclosure?.missing||[]).length?'missing '+item.disclosure.missing.join(', ')+'.':'disclosure and rights evidence is incomplete.'));if(item.state!=='approved')hints.push('Stage as ready needs an approved video.');else if(!item.thumbnail_url)hints.push('Stage as ready needs a thumbnail.');}const hint=node('p',hints.join(' '));hint.id='actionHint';hint.className='text-sm text-tf-muted';hint.hidden=!hints.length;
const sceneList=item.script?.reference_short?.scenes;if(Array.isArray(sceneList)&&sceneList.length){const titles={};for(const source of disclosure.sources||[])titles[source.source_id]=source.title||source.source_id;const strip=node('ol');strip.id='sceneStrip';for(const scene of sceneList){const refs=(scene.source_ids||[]).map(id=>titles[id]||id);strip.append(node('li',`${scene.template||'scene'}: ${scene.vo||''}${refs.length?' [sources: '+refs.join(', ')+']':''}`));}detail.append(node('h3','Scenes beside their sources'),strip);}detail.append(actions,hint,node('h3','Script and beats'),node('pre',JSON.stringify(scriptSummary,null,2)));if(item.available&&item.qa_ok&&item.decision==='approved'&&['approved','ready'].includes(item.state))addPreparePost(item);
}
function addPreparePost(item){
 const section=node('section');section.id='preparePost';section.className='grid gap-3 rounded-lg border border-tf-line bg-tf-surface p-4';
 const heading=node('h3','Prepare publishing draft'),hint=node('p','Choose connected destinations and preview the suggested details. This does not upload or schedule.'),load=node('button','Choose destinations'),body=node('div'),result=node('p');
 load.type='button';result.setAttribute('role','status');section.append(heading,hint,load,body,result);detail.querySelector('#actions').after(section);
 load.onclick=async()=>{load.disabled=true;result.textContent='Loading destinations and suggestions…';try{
  const [a,b]=await Promise.all([fetch('/api/social-accounts'),fetch('/api/batch-plans/'+encodeURIComponent(item.id)+'/post-defaults?reviewed_identity='+encodeURIComponent(item.reviewed_identity))]);
  if(!a.ok||!b.ok)throw Error('Could not load destinations or this approval has changed.');const accounts=(await a.json()).filter(x=>x.status==='connected'&&!x.disabled&&x.external_account_id&&['youtube','instagram'].includes(x.platform)),defaults=await b.json();
  if(selected?.id!==item.id||selected?.reviewed_identity!==item.reviewed_identity)return;
  body.replaceChildren();if(!accounts.length){result.textContent='No connected YouTube or Instagram accounts. Connect an account first.';return;}
  const picks=[];for(const account of accounts){const label=node('label'),check=node('input');check.type='checkbox';check.value=account.id;label.append(check,document.createTextNode(' '+account.platform+' · '+account.display_name));body.append(label);picks.push(check);}
  for(const platform of ['youtube','instagram']){if(!accounts.some(x=>x.platform===platform))continue;const box=node('details'),summary=node('summary',platform==='youtube'?'YouTube suggested title and description':'Instagram suggested caption');box.append(summary);const content=node('p',platform==='youtube'?defaults.youtube.title+'\n\n'+defaults.youtube.caption:defaults.instagram.caption);content.className='whitespace-pre-wrap text-sm';box.append(content);body.append(box);}
  const save=node('button','Create draft');save.type='button';body.append(save);result.textContent='Instagram posts are public; publishing remains unavailable until its integration is ready.';
  save.onclick=async()=>{const ids=picks.filter(x=>x.checked).map(x=>x.value);if(!ids.length){result.textContent='Select at least one destination.';return;}save.disabled=true;result.textContent='Preparing reviewed draft…';try{const csrf=decodeURIComponent((document.cookie.match(/(?:^|; )tubeforge_csrf=([^;]+)/)||[])[1]||'');const response=await fetch('/api/batch-plans/'+encodeURIComponent(item.id)+'/prepare-post',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrf},body:JSON.stringify({reviewed_identity:item.reviewed_identity,destination_account_ids:ids})});const data=await response.json();if(!response.ok)throw Error(typeof data.detail==='string'?data.detail:'Could not create the draft.');body.replaceChildren();result.textContent='Draft created. Review its exact details in Publishing before any submission.';const link=node('a','Open Publishing');link.href='/#publishing';body.append(link);}catch(e){result.textContent=e.message;save.disabled=false;}};
 }catch(e){result.textContent=e.message;}finally{load.disabled=false;}};
}
async function refreshSafety(){try{const response=await fetch('/api/batch-plans/safety-report'+(day.value?'?day='+encodeURIComponent(day.value):''));if(!response.ok)throw Error('Channel checks unavailable.');const report=await response.json();document.querySelector('#safetyStatus').textContent='';const nextSafetySignature=JSON.stringify(report);if(nextSafetySignature===safetySignature)return;safetySignature=nextSafetySignature;const target=document.querySelector('#safetyWarnings');target.replaceChildren();const pretty=text=>String(text).split('_').join(' ');const pairs=report.similar_and_close||[];for(const pair of pairs){target.append(node('li',`Similar and planned ${Math.round(pair.minutes)} min apart (minimum ${pair.minimum_minutes}): ${pair.ids.join(' + ')} - ${pair.reasons.map(pretty).join(', ')}`));}const warnings=[...report.repetition.warnings,...report.cadence.warnings];for(const warning of warnings){target.append(node('li',`${warning.ids.join(', ')}: ${warning.code?pretty(warning.code):warning.reasons.map(r=>pretty(r.code)).join(', ')}`));}for(const entry of report.repetition.entries||[]){if((entry.unknown_fields||[]).length)target.append(node('li',`${entry.id}: unknown ${entry.unknown_fields.map(pretty).join(', ')} (no render evidence, so not compared)`));}if(!warnings.length&&!pairs.length)target.append(node('li','No warnings in the available plan and render evidence.'));const scope=report.cadence.scope;if(scope)target.append(node('li',`Info: cadence is shown for ${scope.day} only (${scope.all_warnings} warnings across all plans).`));for(const [channel,limits] of Object.entries(report.cadence.resolved_limits||{}))target.append(node('li',`Info: limits for ${channel}: at most ${limits.max_per_day} a day, ${limits.min_spacing_minutes} min apart, timezone ${limits.timezone}.`));}catch(e){document.querySelector('#safetyStatus').textContent=e.message+(safetySignature?' Showing the last loaded warnings.':'')+' Retry Refresh.';}}
async function refresh(explicit=false){refreshSafety();try{const response=await fetch('/api/batch-plans/review'+(day.value?'?day='+encodeURIComponent(day.value):''));if(!response.ok)throw Error('Could not refresh review queue.');items=await response.json();const nextSignature=JSON.stringify(items.map(x=>[x.id,x.state,x.decision,x.production_state,x.reviewed_identity,x.qa_ok,x.export_url]));if(nextSignature!==signature){signature=nextSignature;list.replaceChildren();for(const item of items){const li=node('li'),button=node('button',`${item.short.title} · ${item.state} · ${item.production_state}`);button.type='button';button.className='w-full justify-start text-left';button.onclick=()=>show(item);li.append(button);if(item.export_url){const link=node('a','Open export');link.href=item.export_url;link.target='_blank';link.rel='noopener';li.append(link);}list.append(li);}if(!items.length)list.append(node('li','No shorts for this day. Import a plan or choose another day.'));}if(selected){const current=items.find(x=>x.id===selected.id);if(explicit&&current)show(current);else if(!current||current.reviewed_identity!==selected.reviewed_identity){detail.querySelectorAll('#actions button').forEach(b=>b.disabled=true);document.querySelector('#preparePost')?.remove();const staleHint=[...detail.children].find(x=>x.id==='actionHint');if(staleHint){staleHint.textContent=current?'Review actions are off because the selected artifact changed. Select it again.':'Review actions are off because this short is not in the current list. Select it again from the list.';staleHint.hidden=false;}const link=[...detail.children].find(x=>x.id==='exportLink');if(link)link.hidden=true;notice.textContent=current?'The selected artifact changed. Select it again before reviewing.':'The selected short is not in the current list (a different day?). Select it again before reviewing.';}else{selected=current;const exportLink=[...detail.children].find(x=>x.id==='exportLink');if(exportLink){exportLink.hidden=!current.export_url;exportLink.href=current.export_url||'#';}const label=[...detail.children].find(x=>x.id==='reviewStatus');if(label)label.textContent=`Review: ${current.state}${current.decision?' · '+current.decision:''} · Production: ${current.production_state}`;detail.querySelectorAll('#actions button').forEach(b=>{const a=b.dataset.action;b.disabled=busy||!current.available||(a==='approve'&&(!current.qa_ok||!current.disclosure?.eligible))||(a==='ready'&&(!current.qa_ok||current.state!=='approved'||!current.thumbnail_url));});}}if(explicit||!selected)notice.textContent=items.length?`${items.length} shorts · select a video to review.`:'No videos to review.';}catch(e){notice.textContent=e.message+' Showing the last loaded data.';}}
const CONFIRM_TEXT={reject:'Reject this exact video? Any approval of it is dropped and it goes back to needs review.',regenerate:'Regenerate creates a new generation for this short. The current video is kept, and the new script and preview need fresh approval in Generations.'};
let pendingConfirm=null;
function closeConfirm(){if(pendingConfirm&&pendingConfirm.parentNode===detail)detail.removeChild(pendingConfirm);pendingConfirm=null;}
function askConfirm(action){if(busy||!selected)return;closeConfirm();const bar=node('div');bar.id='confirmBar';bar.className='grid gap-3 rounded-lg border border-tf-bad bg-tf-bad-soft p-4';bar.setAttribute('role','group');bar.setAttribute('aria-label','Confirm '+action);const text=node('p',CONFIRM_TEXT[action]);const yes=node('button','Confirm '+action);yes.type='button';yes.dataset.confirm=action;yes.onclick=()=>{closeConfirm();decide(action)};const no=node('button','Cancel');no.type='button';no.onclick=()=>{closeConfirm()};const row=node('div');row.className='flex flex-wrap gap-2';row.append(yes,no);bar.append(text,row);const anchor=Array.from(detail.children).find(x=>x.id==='actions');if(anchor&&anchor.nextSibling)detail.insertBefore(bar,anchor.nextSibling);else detail.append(bar);pendingConfirm=bar;if(yes.focus)yes.focus();}
async function decide(action){if(busy||!selected)return;const choice=document.querySelector('#disclosureChoice')?.value;if(action==='approve'&&!choice){notice.textContent='Choose the platform disclosure decision before approving.';return;}busy=true;detail.querySelectorAll('#actions button').forEach(b=>b.disabled=true);notice.textContent=action==='regenerate'?'Creating a new generation…':'Saving review decision…';try{const csrf=decodeURIComponent((document.cookie.match(/(?:^|; )tubeforge_csrf=([^;]+)/)||[])[1]||'');const response=await fetch('/api/batch-plans/'+encodeURIComponent(selected.id)+'/review',{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrf},body:JSON.stringify({action,reviewed_identity:selected.reviewed_identity,disclosure_required:action==='approve'?choice==='yes':null})});const data=await response.json();if(!response.ok)throw Error(data.detail||'Review action failed');busy=false;await refresh(true);notice.textContent=action==='regenerate'?'New job created. Fresh script and preview approvals are required in Generations.':`Saved: ${data.state}${data.decision?' · '+data.decision:''}`;}catch(e){notice.textContent=e.message;busy=false;if(selected)show(selected);}finally{busy=false;}}
day.onchange=()=>{selected=null;detail.replaceChildren(node('p','Select a short to review.'));refresh(true)};document.querySelector('#refresh').onclick=()=>refresh(true);refresh(true);setInterval(()=>{if(!busy)refresh(false)},10000);
''' + STUDIO_STATIC_MENU_SCRIPT + '''
</script></html>'''
    )


REVIEW_HTML = render_review_html(None)
